// Run with node --import tsx scripts/generate-lesson-catalog.mjs after editing local seed data.
import { lessons, learningPaths, categories } from "../src/data/coffeeData.ts";
import { writeFileSync } from "node:fs";
writeFileSync(
  new URL("../src/data/lessonCatalog.ts", import.meta.url),
  "// Generated by scripts/generate-lesson-catalog.mjs. No lesson bodies are sent to the shared UI.\n" +
    "export const lessons = " +
    JSON.stringify(lessons.map(({ id, category }) => ({ id, category }))) +
    ";\n" +
    "export const learningPaths = " +
    JSON.stringify(learningPaths) +
    ";\n" +
    "export const categories = " +
    JSON.stringify(categories) +
    ";\n",
);
